import json
import math
import sqlite3
from typing import Dict, Any, List, Tuple

# ---------- Config (MUST match provided paths/config) ----------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_cfg = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_cfg = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# ---------- Helpers ----------
def safe_json_loads(s: Any) -> Dict[str, Any]:
    if s is None:
        return {}
    if isinstance(s, dict):
        return s
    if not isinstance(s, str):
        return {}
    s = s.strip()
    if not s:
        return {}
    try:
        return json.loads(s)
    except Exception:
        return {}


def table_columns(conn: sqlite3.Connection, table: str) -> List[str]:
    cur = conn.cursor()
    cur.execute(f"PRAGMA table_info({table})")
    return [r[1] for r in cur.fetchall()]


def norm01(x: float, xmin: float, xmax: float) -> float:
    if xmax <= xmin:
        return 0.0
    return max(0.0, min(1.0, (x - xmin) / (xmax - xmin)))


# ---------- Step 1: SQL candidates ----------
def get_candidates(city: str = "Santa Barbara", min_stars: float = 3.5, limit: int = 500) -> List[Dict[str, Any]]:
    conn = sqlite3.connect(sqlite_paths["business"])
    conn.row_factory = sqlite3.Row

    cols = set(table_columns(conn, "business"))

    select_cols = ["business_id", "name", "address", "city", "state", "postal_code", "stars", "review_count", "categories"]
    if "attributes" in cols:
        select_cols.append("attributes")

    # Basic filter: city + restaurants + stars
    sql = f"""
    SELECT {', '.join(select_cols)}
    FROM business
    WHERE city = ?
      AND categories LIKE '%Restaurants%'
      AND stars >= ?
    ORDER BY review_count DESC
    LIMIT ?
    """

    cur = conn.cursor()
    cur.execute(sql, (city, min_stars, limit))
    rows = [dict(r) for r in cur.fetchall()]
    conn.close()

    # Prefer group-friendly attributes if present
    out = []
    for r in rows:
        attrs = safe_json_loads(r.get("attributes"))
        good_for_groups = attrs.get("RestaurantsGoodForGroups")
        reservations = attrs.get("RestaurantsReservations")

        def to_bool(v):
            if isinstance(v, bool):
                return v
            if isinstance(v, str):
                return v.lower() in ("true", "1", "yes")
            return False

        r["_attrs"] = attrs
        r["_good_for_groups"] = to_bool(good_for_groups)
        r["_reservations"] = to_bool(reservations)

        # If attributes exist, keep all but mark; later we score boost for these flags
        out.append(r)

    return out


# ---------- Step 2: Vector search in Milvus reviews ----------
def milvus_review_signal(query_text: str, topk: int = 80) -> Dict[str, float]:
    """Return business_id -> semantic_score (aggregated)"""
    try:
        from pymilvus import connections, Collection
        from sentence_transformers import SentenceTransformer

        connections.connect(alias="default", host=milvus_cfg["milvus_host"], port=milvus_cfg["milvus_port"])
        col = Collection(milvus_cfg['milvus_collections']['reviews'])

        # Build query embedding
        model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
        qvec = model.encode([query_text], normalize_embeddings=True).tolist()

        # Common param choices; adapt if your collection uses different metric
        search_params = {"metric_type": "IP", "params": {"nprobe": 10}}

        # We assume fields include: embedding + business_id (+review_id). If your schema differs, adjust output_fields.
        res = col.search(
            data=qvec,
            anns_field="embedding",
            param=search_params,
            limit=topk,
            output_fields=["business_id", "review_id"],
            consistency_level="Strong"
        )

        biz2score: Dict[str, float] = {}
        for hits in res:
            for h in hits:
                biz_id = None
                try:
                    biz_id = h.entity.get("business_id")
                except Exception:
                    # fallback if entity access differs
                    biz_id = getattr(h, "business_id", None)
                if not biz_id:
                    continue
                score = float(h.score)
                # aggregate: keep max score per business
                biz2score[biz_id] = max(biz2score.get(biz_id, -1e9), score)

        return biz2score

    except Exception as e:
        # If Milvus/model not available, gracefully degrade
        print(f"[WARN] Milvus vector step skipped: {e}")
        return {}


# ---------- Step 4: Graph popularity from Neo4j (optional) ----------
def neo4j_distinct_reviewers(biz_ids: List[str]) -> Dict[str, int]:
    if not biz_ids:
        return {}
    try:
        from neo4j import GraphDatabase

        driver = GraphDatabase.driver(neo4j_cfg['neo4j_uri'], auth=neo4j_cfg['neo4j_auth'])
        cypher = """
        MATCH (u:User)-[:WROTE]->(:Review)-[:ABOUT]->(b:Business)
        WHERE b.business_id IN $biz_ids
        RETURN b.business_id AS business_id, count(DISTINCT u) AS distinct_reviewers
        """
        out = {}
        with driver.session() as session:
            for r in session.run(cypher, biz_ids=biz_ids):
                out[r["business_id"]] = int(r["distinct_reviewers"])
        driver.close()
        return out
    except Exception as e:
        print(f"[WARN] Neo4j graph step skipped: {e}")
        return {}


# ---------- Rank & explain ----------
def rank_restaurants(candidates: List[Dict[str, Any]], biz2vec: Dict[str, float], topn: int = 5) -> List[Dict[str, Any]]:
    if not candidates:
        return []

    stars_vals = [float(c.get("stars", 0.0) or 0.0) for c in candidates]
    rc_vals = [int(c.get("review_count", 0) or 0) for c in candidates]

    smin, smax = min(stars_vals), max(stars_vals)
    rcmin, rcmax = min(rc_vals), max(rc_vals)

    # Normalize vector scores if present
    vec_scores = [biz2vec.get(c["business_id"], None) for c in candidates]
    vec_present = [v for v in vec_scores if v is not None]
    if vec_present:
        vmin, vmax = min(vec_present), max(vec_present)
    else:
        vmin, vmax = 0.0, 1.0

    scored = []
    for c in candidates:
        bid = c["business_id"]
        stars = float(c.get("stars", 0.0) or 0.0)
        rc = int(c.get("review_count", 0) or 0)

        stars_n = norm01(stars, smin, smax)
        # use log to reduce heavy-tail
        rc_n = norm01(math.log1p(rc), math.log1p(rcmin), math.log1p(rcmax))

        vec_raw = biz2vec.get(bid)
        vec_n = norm01(vec_raw, vmin, vmax) if vec_raw is not None else 0.0

        # attribute boosts
        attr_boost = 0.0
        if c.get("_good_for_groups"):
            attr_boost += 0.08
        if c.get("_reservations"):
            attr_boost += 0.05

        # Weighted score: base quality + popularity + semantic evidence + attribute boost
        score = 0.55 * stars_n + 0.25 * rc_n + 0.20 * vec_n + attr_boost

        explanation_bits = []
        if c.get("_good_for_groups"):
            explanation_bits.append("marked GoodForGroups")
        if c.get("_reservations"):
            explanation_bits.append("takes reservations")
        if vec_raw is not None:
            explanation_bits.append("reviews semantically mention large groups/reunions")
        explanation_bits.append(f"stars={stars}")
        explanation_bits.append(f"review_count={rc}")

        scored.append({
            **c,
            "_score": float(score),
            "_why": "; ".join(explanation_bits)
        })

    scored.sort(key=lambda x: x["_score"], reverse=True)
    top = scored[:topn]

    # Optional: Neo4j popularity refinement for top
    biz_ids = [t["business_id"] for t in top]
    biz2pop = neo4j_distinct_reviewers(biz_ids)
    if biz2pop:
        pop_vals = list(biz2pop.values())
        pmin, pmax = min(pop_vals), max(pop_vals)
        for t in top:
            pop = biz2pop.get(t["business_id"], 0)
            pop_n = norm01(pop, pmin, pmax)
            t["_score"] = float(t["_score"] + 0.05 * pop_n)
            if pop > 0:
                t["_why"] += f"; distinct_reviewers={pop}"
        top.sort(key=lambda x: x["_score"], reverse=True)

    return top


def main():
    city = "Santa Barbara"
    # Query text tuned for the user's need
    query_text = "family reunion large group can accommodate a large party private room group reservation"

    candidates = get_candidates(city=city, min_stars=3.5, limit=500)

    # Prefer candidates with group-friendly attributes when available
    # (keep all, but if too many, prioritize those flags)
    if any(c.get("_good_for_groups") or c.get("_reservations") for c in candidates):
        candidates.sort(key=lambda x: (x.get("_good_for_groups", False), x.get("_reservations", False), x.get("review_count", 0)), reverse=True)
        candidates = candidates[:500]

    biz2vec = milvus_review_signal(query_text, topk=80)

    ranked = rank_restaurants(candidates, biz2vec, topn=5)

    if not ranked:
        print("No matching restaurants found. Try lowering min_stars or removing category constraints.")
        return

    print(f"Top options for a large group in {city}:")
    for i, r in enumerate(ranked, 1):
        addr = ", ".join([p for p in [r.get("address"), r.get("city"), r.get("state"), r.get("postal_code")] if p])
        print(f"\n{i}. {r.get('name')}\n   Address: {addr}\n   Stars: {r.get('stars')} | Reviews: {r.get('review_count')}\n   Why: {r.get('_why')}\n   Categories: {r.get('categories')}")


if __name__ == "__main__":
    main()

import sqlite3
import math
import json
import ast
from typing import Any, Dict, List, Tuple

# Milvus
from pymilvus import connections, Collection, utility

# Optional embedding model for query vectors
try:
    from sentence_transformers import SentenceTransformer
except Exception:
    SentenceTransformer = None


def safe_parse_obj(s: Any) -> Any:
    """Parse JSON/dict-like strings from Yelp SQLite fields (attributes/hours).
    Returns Python object or None.
    """
    if s is None:
        return None
    if isinstance(s, (dict, list)):
        return s
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s or s.lower() == 'none':
        return None

    # Try JSON first
    try:
        return json.loads(s)
    except Exception:
        pass

    # Yelp attributes are often stored like a Python dict string with single quotes
    try:
        return ast.literal_eval(s)
    except Exception:
        return None


def parse_hours_to_dict(hours_field: Any) -> Dict[str, str]:
    """Normalize hours field to dict like {'Monday': '17:00-02:00', ...}."""
    obj = safe_parse_obj(hours_field)
    if isinstance(obj, dict):
        return obj
    return {}


def is_open_past_midnight(hours_dict: Dict[str, str]) -> bool:
    """True if any day closes after 00:00 (i.e., close time < open time or close time in 00-05 range)."""
    for _, span in hours_dict.items():
        if not isinstance(span, str) or '-' not in span:
            continue
        try:
            open_t, close_t = span.split('-', 1)
            open_t = open_t.strip()
            close_t = close_t.strip()
            oh, om = [int(x) for x in open_t.split(':')]
            ch, cm = [int(x) for x in close_t.split(':')]
            open_minutes = oh * 60 + om
            close_minutes = ch * 60 + cm

            # Cross-midnight if close earlier than open (e.g., 18:00-02:00)
            if close_minutes < open_minutes:
                return True

            # Some places encode late close as 00:00-05:xx with open earlier not necessarily cross-midnight in data;
            # treat close time between 00:00 and 05:59 as "past midnight".
            if 0 <= close_minutes <= 5 * 60 + 59 and open_minutes <= close_minutes:
                return True
        except Exception:
            continue
    return False


def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def normalize_stars(stars: float) -> float:
    # Yelp stars typically 1.0-5.0
    if stars is None:
        return 0.0
    return max(0.0, min(1.0, (float(stars) - 1.0) / 4.0))


def log_review_count(rc: int) -> float:
    if rc is None or rc <= 0:
        return 0.0
    return min(1.0, math.log10(rc + 1) / 4.0)  # rough cap


def wifi_bonus(attributes_field: Any) -> float:
    attrs = safe_parse_obj(attributes_field)
    if not isinstance(attrs, dict):
        return 0.0
    wifi = attrs.get('WiFi') or attrs.get('wifi')
    if wifi is None:
        return 0.0
    # Common Yelp values: 'free', 'paid', 'no'
    if isinstance(wifi, str):
        w = wifi.strip().strip('"\'').lower()
        if 'free' in w:
            return 1.0
        if 'paid' in w:
            return 0.3
        if w in ('no', 'none'):
            return -0.5
    return 0.0


def get_candidates_businesses(conn_business: sqlite3.Connection) -> List[sqlite3.Row]:
    sql = """
    SELECT business_id, name, address, city, state, postal_code,
           stars, review_count, categories, attributes, hours
    FROM business
    WHERE city=? AND state=? AND is_open=1
      AND (
        categories LIKE '%Coffee%' OR categories LIKE '%Cafes%' OR categories LIKE '%Bars%'
        OR categories LIKE '%Lounges%' OR categories LIKE '%Diners%' OR categories LIKE '%Bakeries%'
        OR categories LIKE '%Tea%' OR categories LIKE '%Desserts%'
      )
    """
    return list(conn_business.execute(sql, ('Tampa', 'FL')).fetchall())


def init_embedder() -> Any:
    """Initialize sentence-transformers for query embedding.

    If you used a different embedding model to build Milvus vectors, replace the model name
    to match that pipeline, otherwise similarity search quality will degrade.
    """
    if SentenceTransformer is None:
        raise RuntimeError(
            "sentence-transformers is not installed. Install with: pip install sentence-transformers"
        )
    return SentenceTransformer('all-MiniLM-L6-v2')


def milvus_connect(milvus_host: str, milvus_port: str):
    connections.connect(alias='default', host=milvus_host, port=milvus_port)


def milvus_collection(name: str) -> Collection:
    if not utility.has_collection(name):
        raise RuntimeError(f"Milvus collection not found: {name}")
    col = Collection(name)
    col.load()
    return col


def detect_vector_field(col: Collection) -> str:
    # heuristic: first FLOAT_VECTOR/FLOAT16/BINARY_VECTOR field
    for f in col.schema.fields:
        t = str(f.dtype)
        if 'VECTOR' in t:
            return f.name
    raise RuntimeError(f"No vector field found in collection {col.name}")


def detect_id_fields(col: Collection) -> Tuple[str, str]:
    """Try to detect (doc_id_field, business_id_field) by common names."""
    field_names = {f.name for f in col.schema.fields}
    doc_candidates = ['review_id', 'tip_id', 'id', 'doc_id']
    biz_candidates = ['business_id', 'biz_id']
    doc_field = next((x for x in doc_candidates if x in field_names), None)
    biz_field = next((x for x in biz_candidates if x in field_names), None)
    return doc_field, biz_field


def milvus_semantic_search(
    col: Collection,
    query_vec: List[float],
    limit: int = 200,
    expr: str = None
) -> List[Dict[str, Any]]:
    vec_field = detect_vector_field(col)
    doc_field, biz_field = detect_id_fields(col)

    # Search params may need to match your index type
    search_params = {"metric_type": "IP", "params": {"nprobe": 16}}

    output_fields = []
    if doc_field:
        output_fields.append(doc_field)
    if biz_field:
        output_fields.append(biz_field)

    res = col.search(
        data=[query_vec],
        anns_field=vec_field,
        param=search_params,
        limit=limit,
        expr=expr,
        output_fields=output_fields
    )

    hits_out = []
    for hit in res[0]:
        item = {
            "score": float(hit.score),
            "distance": float(getattr(hit, 'distance', 0.0))
        }
        # hit.entity may not exist in older versions; use hit.get
        try:
            if doc_field:
                item[doc_field] = hit.entity.get(doc_field)
            if biz_field:
                item[biz_field] = hit.entity.get(biz_field)
        except Exception:
            # fallback
            if doc_field:
                item[doc_field] = hit.get(doc_field)
            if biz_field:
                item[biz_field] = hit.get(biz_field)
        hits_out.append(item)
    return hits_out


def fetch_review_text(conn_review: sqlite3.Connection, review_id: str) -> Dict[str, Any]:
    row = conn_review.execute(
        "SELECT review_id, business_id, stars, date, text FROM review WHERE review_id=?",
        (review_id,)
    ).fetchone()
    return dict(row) if row else {}


def fetch_tip_text(conn_tip: sqlite3.Connection, tip_id: str) -> Dict[str, Any]:
    row = conn_tip.execute(
        "SELECT tip_id, business_id, date, text FROM tip WHERE tip_id=?",
        (tip_id,)
    ).fetchone()
    return dict(row) if row else {}


def main(top_n: int = 10):
    # --- Required exact configuration ---
    sqlite_paths = {
        "business": "D:/Yelp-JSON/db/sqlite3/business.db",
        "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
        "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
        "review": "D:/Yelp-JSON/db/sqlite3/review.db",
        "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
        "user": "D:/Yelp-JSON/db/sqlite3/user.db"
    }

    milvus_cfg = {
        'milvus_collections': {
            'reviews': 'reviews',
            'photos': 'photo_vector',
            'tips': 'milvus_tip'
        },
        'milvus_host': 'localhost',
        'milvus_port': '19530'
    }

    neo4j_cfg = {
        'neo4j_uri': 'bolt://localhost:7687',
        'neo4j_auth': ('neo4j', 'password')
    }
    # (neo4j_cfg is present to match the architecture; not required for this specific workflow.)

    # --- Connect SQLite ---
    conn_business = connect_sqlite(sqlite_paths['business'])
    conn_review = connect_sqlite(sqlite_paths['review'])
    conn_tip = connect_sqlite(sqlite_paths['tip'])

    # --- Step 1: SQL candidates ---
    candidates = get_candidates_businesses(conn_business)

    # --- Step 2: parse hours, keep late-night ---
    late_night = []
    for r in candidates:
        hours = parse_hours_to_dict(r['hours'])
        if is_open_past_midnight(hours):
            late_night.append((r, hours))

    if not late_night:
        print("No late-night (past midnight) candidates found for Tampa with the current category filter.")
        return

    biz_rows = [x[0] for x in late_night]
    biz_hours = {x[0]['business_id']: x[1] for x in late_night}
    biz_ids = [r['business_id'] for r in biz_rows]

    # --- Connect Milvus ---
    milvus_connect(milvus_cfg['milvus_host'], milvus_cfg['milvus_port'])
    col_reviews = milvus_collection(milvus_cfg['milvus_collections']['reviews'])
    col_tips = milvus_collection(milvus_cfg['milvus_collections']['tips'])

    # --- Embed the intent query ---
    embedder = init_embedder()
    query_text = (
        "late night place to work on laptop in Tampa with good wifi, power outlets, "
        "quiet corner, not too sterile, open past midnight"
    )
    qvec = embedder.encode([query_text], normalize_embeddings=True)[0].tolist()

    # --- Step 3: Review semantic evidence ---
    # Try to use Milvus expr filter if collection has business_id field.
    _, biz_field_reviews = detect_id_fields(col_reviews)
    expr_reviews = None
    if biz_field_reviews:
        # Milvus has a max expr length; for large lists you may need batching.
        quoted = ",".join([f'"{bid}"' for bid in biz_ids[:2000]])
        expr_reviews = f"{biz_field_reviews} in [{quoted}]"

    review_hits = milvus_semantic_search(col_reviews, qvec, limit=400, expr=expr_reviews)

    # --- Step 4: Tip semantic evidence ---
    _, biz_field_tips = detect_id_fields(col_tips)
    expr_tips = None
    if biz_field_tips:
        quoted = ",".join([f'"{bid}"' for bid in biz_ids[:2000]])
        expr_tips = f"{biz_field_tips} in [{quoted}]"

    tip_hits = milvus_semantic_search(col_tips, qvec, limit=400, expr=expr_tips)

    # --- Aggregate evidence per business ---
    # Note: if Milvus collections do NOT store business_id, we will intersect after fetching text.
    per_biz = {bid: {
        "review_matches": [],
        "tip_matches": [],
        "semantic_score": 0.0
    } for bid in biz_ids}

    # Reviews
    for h in review_hits:
        review_id = h.get('review_id')
        biz_id = h.get('business_id')

        if not biz_id and review_id:
            rt = fetch_review_text(conn_review, review_id)
            biz_id = rt.get('business_id')
        else:
            rt = fetch_review_text(conn_review, review_id) if review_id else {}

        if not biz_id or biz_id not in per_biz:
            continue

        text = (rt.get('text') or '').strip().replace('\n', ' ')
        snippet = text[:240] + ('...' if len(text) > 240 else '')
        per_biz[biz_id]["review_matches"].append({
            "score": h.get('score', 0.0),
            "review_id": review_id,
            "snippet": snippet
        })

    # Tips
    for h in tip_hits:
        tip_id = h.get('tip_id')
        biz_id = h.get('business_id')

        if not biz_id and tip_id:
            tt = fetch_tip_text(conn_tip, tip_id)
            biz_id = tt.get('business_id')
        else:
            tt = fetch_tip_text(conn_tip, tip_id) if tip_id else {}

        if not biz_id or biz_id not in per_biz:
            continue

        text = (tt.get('text') or '').strip().replace('\n', ' ')
        snippet = text[:240] + ('...' if len(text) > 240 else '')
        per_biz[biz_id]["tip_matches"].append({
            "score": h.get('score', 0.0),
            "tip_id": tip_id,
            "snippet": snippet
        })

    # Compute semantic score: take top-k average from review+tip hits
    for bid, d in per_biz.items():
        scores = [m['score'] for m in d['review_matches'][:5]] + [m['score'] for m in d['tip_matches'][:5]]
        d['semantic_score'] = sum(scores) / len(scores) if scores else 0.0

    # --- Final ranking ---
    ranked = []
    for r in biz_rows:
        bid = r['business_id']
        sem = per_biz.get(bid, {}).get('semantic_score', 0.0)
        stars_n = normalize_stars(r['stars'])
        rc_n = log_review_count(r['review_count'])
        wifi_b = wifi_bonus(r['attributes'])

        # Weights can be tuned
        final = 0.55 * sem + 0.25 * stars_n + 0.15 * rc_n + 0.05 * max(0.0, wifi_b)

        ranked.append((final, r))

    ranked.sort(key=lambda x: x[0], reverse=True)

    # --- Output ---
    print(f"Late-night work-friendly candidates in Tampa (open past midnight): {len(biz_rows)}")
    print(f"Top {top_n} recommendations (ranked by semantic evidence + rating signals):\n")

    for i, (score, r) in enumerate(ranked[:top_n], start=1):
        bid = r['business_id']
        hours = biz_hours.get(bid, {})
        attrs = safe_parse_obj(r['attributes']) or {}
        wifi = attrs.get('WiFi') if isinstance(attrs, dict) else None

        print(f"#{i}  {r['name']}  (score={score:.4f})")
        print(f"    {r['address']}, {r['city']}, {r['state']} {r['postal_code']}")
        print(f"    stars={r['stars']}  review_count={r['review_count']}  WiFi_attr={wifi}")

        # Show a couple of late-night hours lines
        if hours:
            # print up to 3 days
            sample_days = list(hours.items())[:3]
            print("    hours(sample): " + "; ".join([f"{d}:{h}" for d, h in sample_days]))

        ev = per_biz.get(bid, {})
        revs = (ev.get('review_matches') or [])[:2]
        tips = (ev.get('tip_matches') or [])[:2]
        if revs or tips:
            print("    evidence:")
            for m in revs:
                print(f"      [review] {m['snippet']}")
            for m in tips:
                print(f"      [tip] {m['snippet']}")
        else:
            print("    evidence: (no strong semantic hits; may still be late-night but reviews/tips didn't mention wifi/outlets/quiet explicitly)")

        print("")


